feed:
{{ config.title }}{% if term %} - {{ term.name }}{% endif %}
{%- if config.description %}
{{ config.description }}
{%- endif %}

{%- set feed_home = config.base_url ~ config.extra.i18n.root[lang] %}

Zola
{#- 某种语言还没有文章时 Zola 不提供 last_updated，用当前时间 -#}
{%- if last_updated is defined %}{% set_global feed_updated = last_updated %}{% else %}{% set_global feed_updated = now() %}{% endif %}
{{ feed_updated | date(format="%+") }}
{{ feed_url | safe }}
{%- set listed_pages = [] -%}
{%- for p in pages -%}
    {%- if not p.extra.unlisted -%}
        {%- set_global listed_pages = listed_pages | concat(with=p) -%}
    {%- endif -%}
{%- endfor -%}
{%- for page in listed_pages | slice(end=20) %}

    {{ page.title }}
    {{ page.date | date(format="%+") }}
    {{ page.updated | default(value=page.date) | date(format="%+") }}

        {% if page.authors %}{{ page.authors[0] }}{% elif config.extra.author %}{{ config.extra.author }}{% else %}Unknown{% endif %}


    {{ page.permalink | safe }}
    {%- if page.summary %}
    {{ page.summary }}
    {%- else %}
    {{ page.content }}
    {%- endif %}

{%- endfor %}
